from ta_moler.device.nokia_unix_remote3 import NokiaUnixRemote3
from moler.helpers import call_base_class_method_with_same_name, mark_to_call_base_class_method_with_same_name


@call_base_class_method_with_same_name
class BtsSm3(NokiaUnixRemote3):
    r"""
    BtsSm3 device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
      BtsSm3:
       DEVICE_CLASS: ta_moler.device.btssm3.BtsSm3
       CONNECTION_HOPS:
         UNIX_LOCAL:
           PROXY_PC:
             execute_command: ssh # default value
             command_params:
               expected_prompt: proxy_pc_prompt
               host: host_ip
               login: login
               password: password
         PROXY_PC:
           UNIX_REMOTE:
             execute_command: ssh # default value
             command_params:
               expected_prompt: 'ute@[\w-]+:(?!(/opt/Nokia/Managers/BTS Site/BTS Site Manager\$\s+))' # default value
               host: host_ip
               login: login
               password: password
         UNIX_REMOTE:
           CLI:
             execute_command: cd # default value
             command_params:
               path:  "'/opt/Nokia/Managers/BTS Site/BTS Site Manager/'" # default value
               expected_prompt: 'ute@[\w-]+:/opt/Nokia/Managers/BTS Site/BTS Site Manager\$\s+' # default value
           PROXY_PC:
             command_params:
               expected_prompt: proxy_pc_prompt
         CLI:
           UNIX_REMOTE:
             execute_command: cd # default value
             command_params:
               path:  '~' # default value
               expected_prompt: 'ute@[\w-]+:(?!(/opt/Nokia/Managers/BTS Site/BTS Site Manager\$\s+))' # default value
    - without PROXY_PC:
      BtsSm3:
       DEVICE_CLASS: ta_moler.device.btssm3.BtsSm3
       CONNECTION_HOPS:
         UNIX_LOCAL:
           UNIX_REMOTE:
             execute_command: ssh # default value
             command_params:
               expected_prompt: 'ute@[\w-]+:(?!(/opt/Nokia/Managers/BTS Site/BTS Site Manager\$\s+))' # default value
               host: host_ip
               login: login
               password: password
         UNIX_REMOTE:
           CLI:
             execute_command: cd # default value
             command_params:
               path:  "'/opt/Nokia/Managers/BTS Site/BTS Site Manager/'" # default value
               expected_prompt: 'ute@[\w-]+:/opt/Nokia/Managers/BTS Site/BTS Site Manager\$\s+' # default value
         CLI:
           UNIX_REMOTE:
             execute_command: cd # default value
             command_params:
               path:  '~' # default value
               expected_prompt: 'ute@[\w-]+:(?!(/opt/Nokia/Managers/BTS Site/BTS Site Manager\$\s+))' # default value
    """

    cli = "CLI"

    def __init__(self, sm_params, name=None, io_connection=None, io_type=None, variant=None, io_constructor_kwargs=None,
                 initial_state=None, lazy_cmds_events=False):
        """
        Create BtsSm3 device communicating over io_connection.

        :param sm_params: dict with parameters of state machine for device
        :param name: name of device
        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: type of connection - tcp, udp, ssh, telnet, ...
        :param variant: connection implementation variant, ex. 'threaded', 'twisted', 'asyncio', ...
                        (if not given then default one is taken)
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: name of initial state. State machine tries to enter this state just after creation.
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        initial_state = initial_state if initial_state is not None else BtsSm3.cli
        super(BtsSm3, self).__init__(name=name, io_connection=io_connection,
                                     io_type=io_type, variant=variant,
                                     io_constructor_kwargs=io_constructor_kwargs,
                                     sm_params=sm_params, initial_state=initial_state,
                                     lazy_cmds_events=lazy_cmds_events)

    def _get_btssm_default_sm_configuration(self):
        config = {
            BtsSm3.connection_hops: {
                BtsSm3.unix_remote: {  # from
                    BtsSm3.cli: {  # to
                        "execute_command": "cd",  # using command
                        "command_params": {  # with parameters
                            "path": "'/opt/Nokia/Managers/BTS Site/BTS Site Manager/'",
                            "expected_prompt": r"ute@[\w-]+:\/opt\/Nokia\/Managers\/BTS Site\/BTS Site Manager\$\s+",
                        },
                        "required_command_params": [
                        ]
                    }
                },
                BtsSm3.cli: {
                    BtsSm3.unix_remote: {
                        "execute_command": "cd",  # using command
                        "command_params": {  # with parameters
                            "path": "~",
                            "expected_prompt": r"ute@[\w-]+:(?!(\/opt\/Nokia\/Managers\/BTS Site\/BTS Site Manager\$\s+))",
                        },
                        "required_command_params": [
                        ]
                    }
                }
            }
        }
        return config

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_with_proxy_pc(self):
        """
        Return State Machine default configuration with proxy_pc state.

        :return: default sm configuration with proxy_pc state.
        """
        return self._get_btssm_default_sm_configuration()

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_without_proxy_pc(self):
        """
        Return State Machine default configuration without proxy_pc state.

        :return: default sm configuration without proxy_pc state.
        """
        return self._get_btssm_default_sm_configuration()

    def _prepare_btssm_transitions(self):
        transitions = {
            BtsSm3.cli: {
                BtsSm3.unix_remote: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            BtsSm3.unix_remote: {
                BtsSm3.cli: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
            }
        }
        return transitions

    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_with_proxy_pc(self):
        """
        Prepare transitions to change states with proxy_pc state.

        :return: transitions with proxy_pc state.
        """
        return self._prepare_btssm_transitions()

    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_without_proxy_pc(self):
        """
        Prepare transitions to change states without proxy_pc state.

        :return: transitions without proxy_pc state.
        """
        return self._prepare_btssm_transitions()

    def _prepare_btssm_state_prompts(self):
        state_prompts = {
            BtsSm3.cli:
                self._configurations[BtsSm3.connection_hops][BtsSm3.unix_remote][BtsSm3.cli][
                    "command_params"]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        return self._prepare_btssm_state_prompts()

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_without_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine without proxy_pc state.

        :return: textual prompt for each state without proxy_pc state.
        """
        return self._prepare_btssm_state_prompts()

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        """
        Prepare non direct transitions for each state for State Machine with proxy_pc state.

        :return: non direct transitions for each state with proxy_pc state.
        """
        state_hops = {
            BtsSm3.not_connected: {
                BtsSm3.cli: BtsSm3.unix_local
            },
            BtsSm3.unix_local: {
                BtsSm3.cli: BtsSm3.proxy_pc
            },
            BtsSm3.proxy_pc: {
                BtsSm3.cli: BtsSm3.unix_remote
            },
            BtsSm3.unix_local_root: {
                BtsSm3.cli: BtsSm3.unix_local
            },
            BtsSm3.unix_remote_root: {
                BtsSm3.cli: BtsSm3.unix_remote
            },
            BtsSm3.cli: {
                BtsSm3.proxy_pc: BtsSm3.unix_remote,
                BtsSm3.unix_local: BtsSm3.unix_remote,
                BtsSm3.not_connected: BtsSm3.unix_remote,
                BtsSm3.unix_local_root: BtsSm3.unix_remote,
                BtsSm3.unix_remote_root: BtsSm3.unix_remote
            },
        }
        return state_hops

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_without_proxy_pc(self):
        """
        Prepare non direct transitions for each state for State Machine without proxy_pc state.

        :return: non direct transitions for each state without proxy_pc state.
        """
        state_hops = {
            BtsSm3.not_connected: {
                BtsSm3.cli: BtsSm3.unix_local
            },
            BtsSm3.unix_local: {
                BtsSm3.cli: BtsSm3.unix_remote
            },
            BtsSm3.unix_local_root: {
                BtsSm3.cli: BtsSm3.unix_local
            },
            BtsSm3.unix_remote_root: {
                BtsSm3.cli: BtsSm3.unix_remote
            },
            BtsSm3.cli: {
                BtsSm3.unix_local: BtsSm3.unix_remote,
                BtsSm3.not_connected: BtsSm3.unix_remote,
                BtsSm3.unix_local_root: BtsSm3.unix_remote,
                BtsSm3.unix_remote_root: BtsSm3.unix_remote
            }
        }
        return state_hops

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(BtsSm3, self)._get_packages_for_state(state, observer)

        if not available:
            if state == BtsSm3.cli:
                available = {BtsSm3.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix', 'ta_moler.cmd.btssm'],
                             BtsSm3.events: ['moler.events.shared', 'moler.events.unix']}
                return available[observer]

        return available
